 const [mode,setMode]=useState<'welcome'|'demo'|'live'>('welcome');const [token,setToken]=useState('');const [projects,setProjects]=useState<Project[]>([]);const [projectId,setProjectId]=useState('');const [prospects,setProspects]=useState<Prospect[]>([]);const [selected,setSelected]=useState('');const [view,setView]=useState('prospects');const [query,setQuery]=useState('');const [filter,setFilter]=useState('Tous');const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const [draft,setDraft]=useState('');const [draftId,setDraftId]=useState<string|null>(null);const [draftEvidenceIds,setDraftEvidenceIds]=useState<string[]>([]);const [draftStatus,setDraftStatus]=useState<'DRAFT'|'USED'>('DRAFT');const [events,setEvents]=useState<{text:string;at:string}[]>([]);const [modal,setModal]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [weights,setWeights]=useState(DEFAULT_CRITERIA);const [offer,setOffer]=useState('');const [analysis,setAnalysis]=useState('');const [userEmail,setUserEmail]=useState('');const [orgName,setOrgName]=useState('');const [role,setRole]=useState('');const [betaActive,setBetaActive]=useState<boolean|null>(null);const [betaExpiresAt,setBetaExpiresAt]=useState('');const [entitlementPlan,setEntitlementPlan]=useState<string|null>(null);const [legalAccepted,setLegalAccepted]=useState(false);const [deleteStep,setDeleteStep]=useState(0);const [deleteConfirm,setDeleteConfirm]=useState('');const [orgId,setOrgId]=useState('');const [byokAnthropicLast4,setByokAnthropicLast4]=useState<string|null>(null);const [byokAnthropicKey,setByokAnthropicKey]=useState('');const [showDemoHelp,setShowDemoHelp]=useState(false);const [betaAnalytics,setBetaAnalytics]=useState<BetaAnalytics|null>(null);
 const project=projects.find(p=>p.id===projectId);const criteria=project?.criteria??DEFAULT_CRITERIA;const current=prospects.find(p=>p.id===selected);const scored=current?scoreProspect(criteria,current.evidence):null;
 const trialDaysRemaining=betaExpiresAt?Math.max(0,Math.ceil((new Date(betaExpiresAt).getTime()-Date.now())/86400000)):0;
