 async function logout(){if(mode==='live'){try{await auth?.auth.signOut()}catch{}}identity.current=null;setToken('');setUserEmail('');setOrgName('');setRole('');setBetaActive(null);setBetaExpiresAt('');setEntitlementPlan(null);clearWorkspace();setMode('welcome')}
 // Self-service trial: if this account has never had an entitlement row, activate_trial() creates one
 // (server-side, idempotent — see migration 012). Safe to attempt on every login: an account that
