 async function loadBetaAnalytics(){await work(async()=>{setBetaAnalytics(await api('admin/beta-analytics'))})}
 async function loadByokAnthropic(){if(!orgId)return;const rows=await api(`provider-credentials/${orgId}`,'GET');setByokAnthropicLast4(rows.find((r:any)=>r.provider==='anthropic')?.key_last4??null)}
 async function saveByokAnthropic(){if(!orgId)throw Error(tr('error.orgNotFound'));await api(`provider-credentials/${orgId}`,'POST',{provider:'anthropic',api_key:byokAnthropicKey});setByokAnthropicKey('');await loadByokAnthropic();setNotice(tr('account.keySavedNotice'))}
 async function deleteByokAnthropic(){if(!orgId)return;await api(`provider-credentials/${orgId}`,'DELETE',{provider:'anthropic'});setByokAnthropicLast4(null);setNotice(tr('account.keyDeletedNotice'))}
 async function exportAccount(){const res=await fetch('/api/v1/account/export',{method:'POST',headers:{Authorization:`Bearer ${token}`}});if(!res.ok){const d=await res.json().catch(()=>({}));throw Error(d.error??tr('error.exportFailed'))}const blob=await res.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`prospectos-export-${new Date().toISOString().slice(0,10)}.zip`;a.click();URL.revokeObjectURL(url);setNotice(tr('account.exportGeneratedNotice'))}
 async function deleteAccount(){try{await api('account/delete','POST',{confirm:deleteConfirm});await logout()}finally{setModal('');setDeleteStep(0);setDeleteConfirm('')}}
 function demo(){clearWorkspace();let data;try{data=JSON.parse(localStorage.getItem('prospectos-demo-v1')??'null')}catch{}setProjects(data?.projects??[DEMO_PROJECT]);setProspects(data?.prospects??DEMO_PROSPECTS);setProjectId(data?.projects?.[0]?.id??DEMO_PROJECT.id);setSelected(data?.prospects?.[0]?.id??DEMO_PROSPECTS[0].id);setMode('demo');setNotice(tr('demo.notice'));setShowDemoHelp(localStorage.getItem('prospectos-demo-help-dismissed')!=='1');}
