 async function status(value:string){if(!current)return;await work(async()=>{if(mode==='live')await api(`prospects/${current.id}`,'PATCH',{status:value});setProspects(ps=>ps.map(p=>p.id===current.id?{...p,status:value}:p));log(`${tr('log.statusPrefix')}${statusLabel(value,locale)}`)})}
 async function createProject(form:FormData){await work(async()=>{const name=String(form.get('name')??'').trim();const projectOffer=String(form.get('offer')??'').trim();if(!name)throw Error(tr('validation.projectNameRequired'));const starter=DEFAULT_CRITERIA.map(c=>({...c}));let p:Project;if(mode==='demo')p={id:crypto.randomUUID(),organization_id:DEMO_PROJECT.organization_id,name,offer:projectOffer,criteria:starter};else{let orgs=await api('organizations');let org=orgs[0]?.id;if(!org)org=await api('organizations','POST',{name:tr('project.defaultOrgName')});const row=await api('projects','POST',{name,organization_id:org,offer:projectOffer});await api('icps','POST',{project_id:row.id,criteria:starter});p={...row,criteria:starter}}setProjects(ps=>[...ps,p]);setProjectId(p.id);setSelected('');if(mode==='live')setProspects([]);setModal('');setView('icp');setNotice(tr('project.createdNotice'))})}
 async function addProspect(form:FormData){await work(async()=>{const name=String(form.get('name')).trim(),website=String(form.get('website')),city=String(form.get('city')??'');if(!safeLink(website))throw Error(tr('validation.urlRequired'));const data={name,website,city,project_id:projectId};let p:Prospect;if(mode==='demo')p={...data,id:crypto.randomUUID(),organization_id:project!.organization_id,status:'À analyser',evidence:[],channels:[]};else p={...await api('prospects','POST',data),evidence:[],channels:[]};setProspects(ps=>[p,...ps]);setSelected(p.id);setModal('');clearDraft();setNotice(tr('prospect.addedNotice'))})}
 async function addEvidence(form:FormData){if(!current)return;await work(async()=>{const data={criterion:String(form.get('criterion')),value:form.get('value')==='true',source_url:String(form.get('source_url')),excerpt:String(form.get('excerpt')).trim(),observed_at:String(form.get('observed_at')),status:form.get('verified')==='on'?'VERIFIED':'NOT_VERIFIED'};if(!safeLink(data.source_url)||!data.excerpt)throw Error(tr('validation.sourceObservationRequired'));if(+new Date(data.observed_at)>Date.now())throw Error(tr('validation.dateNotFuture'));let e:Evidence;if(mode==='demo')e={...data,id:crypto.randomUUID(),verified_by:data.status==='VERIFIED'?'demo-human':null};else e=await api('evidence','POST',{...data,prospect_id:current.id});setProspects(ps=>ps.map(p=>p.id===current.id?{...p,evidence:[...p.evidence,e]}:p));clearDraft();log(tr('log.evidenceAddedPrefix')+evidenceStatusLabel(data.status,null,locale));setModal('')})}
 async function addChannel(form:FormData){if(!current)return;await work(async()=>{const c:Channel={kind:String(form.get('kind')),value:String(form.get('value')).trim(),source_url:String(form.get('source_url')),verified:form.get('verified')==='on'};if(!safeLink(c.source_url)||(!['phone','email'].includes(c.kind)&&!safeLink(c.value)))throw Error(tr('validation.channelUrlInvalid'));if(mode==='live')await api('channels','POST',{...c,prospect_id:current.id});setProspects(ps=>ps.map(p=>p.id===current.id?{...p,channels:[...p.channels??[],c]}:p));setModal('');log(tr('log.channelDocumented'))})}
 async function importSource(form:FormData){if(!current)return;await work(async()=>{const rows=proposeEvidence(String(form.get('text')),String(form.get('source_url')),criteria);const saved:Evidence[]=[];for(const e of rows){if(mode==='live')saved.push(await api('evidence','POST',{...e,prospect_id:current.id}));else saved.push(e)}setProspects(ps=>ps.map(p=>p.id===current.id?{...p,evidence:[...p.evidence,...saved]}:p));clearDraft();setModal('');setNotice(proposedEvidenceNotice(locale,saved.length))})}
 async function verifyEvidence(e:Evidence){if(!current)return;await work(async()=>{revision.current++;clearDraft();const observations=mode==='live'?await api(`prospects/${current.id}/observations`):JSON.parse(localStorage.getItem(`prospectos-observations:${current.id}`)??'[]');const linked=observations.find((o:{evidence_id:string})=>o.evidence_id===e.id);if(linked){setNotice(tr('evidence.duplicateReviewError'));return}const v=mode==='live'?await api('evidence','POST',{...e,status:'VERIFIED',prospect_id:current.id}):{...e,id:crypto.randomUUID(),status:'VERIFIED',verified_by:'demo-human'};setProspects(ps=>ps.map(p=>p.id===current.id?{...p,evidence:[...p.evidence,v]}:p));log(tr('log.evidenceVerifiedByHuman'))})}

 async function generate(){if(!current||!project)return;await work(async()=>{const r=revision.current;const result=mode==='live'?await api('outreach','POST',{prospect_id:current.id,locale}):{...generateOutreach(current.name,project.offer,criteria,current.evidence,undefined,locale),id:crypto.randomUUID()};if(r!==revision.current)return;setDraft(result.text);setDraftId(result.id??null);setDraftEvidenceIds(result.evidence_ids??[]);setDraftStatus('DRAFT');log(tr('log.draftPrepared'))})}
 async function syncDiscoveryEvidence(evidence?:Evidence[]){revision.current++;clearDraft();if(mode==='demo'&&current&&evidence){setProspects(ps=>ps.map(p=>p.id===current.id?{...p,evidence:[...p.evidence.filter(e=>!evidence.some(n=>n.id===e.id)),...evidence]}:p))}else if(mode==='live'){const r=revision.current;const rows=await api(`prospects?project_id=${projectId}`);if(r===revision.current)setProspects(rows)}}
 function updateCriterion(index:number,patch:Partial<Criterion>){setWeights(ws=>ws.map((w,i)=>i===index?{...w,...patch}:w))}
 // Clears back to no rule at all (rules:undefined) the moment every dimension is emptied, so a
 // half-configured target_fit rule (which the save-time schema would reject) can never be saved by
 // accident — the user simply sees the automation switch itself off until they define something again.
 function updateTargetFitRules(index:number,patch:Partial<TargetFitRules>){setWeights(ws=>ws.map((w,i)=>{if(i!==index)return w;const current=w.rules?.type==='target_fit'?w.rules.config:{match:'any_defined' as const};const config={...current,...patch};const hasAny=!!(config.categories?.length||config.locations?.length||config.org_types?.length);return {...w,rules:hasAny?{type:'target_fit' as const,config}:undefined}}))}
 function updateNeedFitSignals(index:number,signals:string[]){setWeights(ws=>ws.map((w,i)=>i===index?{...w,rules:signals.length?{type:'need_fit' as const,config:{signals}}:undefined}:w))}
