 async function saveIcp(){await work(async()=>{scoreProspect(weights,[]);if(mode==='live'){await api('icps','POST',{project_id:projectId,criteria:weights});await api(`projects/${projectId}`,'PATCH',{offer})}setProjects(ps=>ps.map(p=>p.id===projectId?{...p,criteria:weights,offer}:p));clearDraft();setNotice(tr('icp.savedNotice'))})}
 // Column headers are the only part of this locally-generated CSV that's ever localized — every cell
